int index(std::string_view id){const auto&p=parameters();for(size_t i=0;i<p.size();++i)if(p[i].id==id)return int(i);throw std::runtime_error("Unknown parameter: "+std::string(id));}
Values defaults(){Values v;for(auto&p:parameters())v.push_back(p.def);return v;}
const std::array<std::string,20>& variants(){static std::array<std::string,20> v={"Main Direkt","Main Warm","Main Brillant","Main Radio","Main Aggressiv","Backing Soft","Backing Breit","Harmony Klar","Harmony Warm","Backing Tight","Chor Stadion","Chor Malle","Chor Rau","Chor Breit","Chor Dicht","Chor Hell","Chor Dunkel","Chor Gang","Chor Antwort","Chor Finale"};return v;}
void resolveInto(const Values& b, Values& v){v=b;
 auto get=[&](std::string_view id){return b[size_t(index(id))];};
 auto add=[&](std::string_view id,float d){auto i=size_t(index(id));v[i]=std::clamp(b[i]+d,parameters()[i].min,parameters()[i].max);};
 auto activate=[&](std::string_view id){v[size_t(index(id))]=1;};
 float d=get("druck.amount")*(.7f+get("druck.variant")*.045f);add("fet.threshold",-12*d);add("level.threshold",-8*d);add("fet.makeup",4*d);add("level.makeup",3*d);
 float k=get("klang.amount");add("eq0.gain",-3*k);add("eq2.gain",4*k*(.7f+get("klang.variant")*.045f));add("eq3.gain",3*k);
 float w=get("waerme.amount");add("sat.mix",w*.5f);add("sat.drive",w*get("waerme.variant")*.25f);if(w>0)activate("sat.on");
 float width=get("breite.amount");add("double.mix",width*.6f);add("double.time",width*(.7f+get("breite.variant")*.045f)*10);if(width>0)activate("double.on");
 float room=get("raum.amount");if(room>0){activate("reverb.on");activate("long.on");}add("reverb.send",room*.3f*(.7f+get("raum.variant")*.045f));add("long.send",room*.2f);
 float move=get("bewegung.amount");if(move>0)activate("pump.on");add("pump.depth",move*.5f);add("pump.shape",move*get("bewegung.variant")*.04f);
}
Values resolve(const Values& b){Values v=b;resolveInto(b,v);return v;}
